  },
  "doi_or_stable_url": "https://doi.org/10.1016/j.jhazmat.2024.134646",
  "endpoints": [
    {
      "endpoint_type": "other",
      "evidence_locator_ids": [
        "S09-E08"
      ],
      "interpretation": "PZC of both ZIPGEM and CPS increased after field exposure, attributed to cation (notably Ca2+) adsorption from the water matrix onto media surfaces. This shift implies a more positive surface at given pH, altering electrostatic interactions with PFAS compared to lab-characterized PZC in simple electrolytes.",
      "reported_term": "Point of zero charge (PZC) shift of media in real water matrix"
    },
    {
      "endpoint_type": "other",
      "evidence_locator_ids": [
        "S09-E08",
        "S09-E07"
      ],
      "interpretation": "Adsorbed calcium on media was measured after field operation, and the observed increase in PZC was linked to cation adsorption. Authors highlight that cation adsorption in real waters can significantly modify media surface charge relative to lab conditions, impacting electrostatic PFAS adsorption and cation-bridging interactions.",
      "reported_term": "Cation adsorption onto media"
    }
  ],
  "limitations": [
    {
      "basis": "author_reported",
      "evidence_locator_ids": [
        "S09-E08"
      ],
      "statement": "Authors note that PZC measured in laboratory electrolytes with only H+/OH- as potential-determining ions may be misleading for predicting PFAS adsorption in real water matrices containing multiple counter- and co-ions."
    },
    {
      "basis": "design_inferred",
      "evidence_locator_ids": [
        "S09-E08"
      ],
      "statement": "Quantitative calcium loading on media was not provided in the supplied text, limiting direct linkage between specific cation coverage and magnitude of PZC shift or PFAS removal changes."
    }
  ],
  "matrix": {
    "evidence_locator_ids": [
      "S09-E08"
    ],
    "value": "Field-exposed CPS and ZIPGEM media in contact with surface water containing multiple counter- and co-ions (including calcium) rather than simple electrolyte solution"
  },
