      "evidence_locator_ids": [
        "S09-E08"
      ],
      "name": "PZC measurement context",
      "qualifiers": "Authors caution that lab PZC in simple electrolyte can be misleading for field behavior and therefore measured PZC on field samples.",
      "unit": null,
      "value": "PZC for fresh media measured in laboratory electrolyte where H+/OH- are the only potential determining ions; PZC for field-exposed media measured after operation in canal water with multiple ions."
